{"task": "customer-fk", "steps": [
  {"note": "Pre-check, read-only: if the FK is not already in place and validated, stop before touching anything when orders reference customers that don't exist. The FK can't hold on that data, and fixing it would mean changing data.",
   "sql": "SET statement_timeout = 0; DO $$ DECLARE n bigint; BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND contype = 'f' AND convalidated AND pg_get_constraintdef(oid) = 'FOREIGN KEY (customer_id) REFERENCES customers(id)') THEN RAISE NOTICE 'FK already present and validated, nothing to check'; RETURN; END IF; SELECT count(*) INTO n FROM public.orders o WHERE NOT EXISTS (SELECT 1 FROM public.customers c WHERE c.id = o.customer_id); IF n > 0 THEN RAISE EXCEPTION '% orders reference missing customers; not adding the FK', n; END IF; RAISE NOTICE 'no orphan orders'; END $$;"},
  {"note": "Add the FK as NOT VALID: catalog-only, instant, enforced for new and updated rows from now on. It briefly needs a SHARE ROW EXCLUSIVE lock on orders and customers, so lock_timeout is 300 ms. That way app queries never queue behind it for long (they have a 2 s timeout), and it retries up to 60 times. Skipped if an FK on orders(customer_id) -> customers(id) already exists.",
   "sql": "SET statement_timeout = 0; DO $$ DECLARE i int; BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND contype = 'f' AND pg_get_constraintdef(oid) LIKE 'FOREIGN KEY (customer_id) REFERENCES customers(id)%') THEN RAISE NOTICE 'FK already exists, skipping add'; RETURN; END IF; PERFORM set_config('lock_timeout', '300ms', true); FOR i IN 1..60 LOOP BEGIN ALTER TABLE public.orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(id) NOT VALID; RAISE NOTICE 'FK added NOT VALID on attempt %', i; RETURN; EXCEPTION WHEN lock_not_available THEN PERFORM pg_sleep(0.5 + random()); END; END LOOP; RAISE EXCEPTION 'could not get the lock to add the FK after 60 attempts'; END $$;"},
  {"note": "Validate the existing rows. VALIDATE CONSTRAINT takes only SHARE UPDATE EXCLUSIVE on orders and ROW SHARE on customers, so app reads and inserts keep running while it scans the 10M rows. No statement timeout. Skipped if the FK is already validated.",
   "sql": "SET statement_timeout = 0; SET lock_timeout = '10s'; DO $$ DECLARE n name; BEGIN SELECT conname INTO n FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND contype = 'f' AND NOT convalidated AND pg_get_constraintdef(oid) LIKE 'FOREIGN KEY (customer_id) REFERENCES customers(id)%'; IF n IS NULL THEN RAISE NOTICE 'nothing to validate'; RETURN; END IF; EXECUTE format('ALTER TABLE public.orders VALIDATE CONSTRAINT %I', n); RAISE NOTICE 'validated %', n; END $$;"},
  {"note": "Verify: a validated FK orders(customer_id) -> customers(id) exists.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND contype = 'f' AND convalidated AND pg_get_constraintdef(oid) = 'FOREIGN KEY (customer_id) REFERENCES customers(id)') THEN RAISE EXCEPTION 'validated FK orders.customer_id -> customers.id not found'; END IF; RAISE NOTICE 'OK: validated FK in place'; END $$;"}
]}
